import type { Locale } from "@/shared/i18n/config";

/**
 * Guides (Help Center). Content lives in this folder; screenshots + marker rectangles are generated by
 * `pnpm guides:shots` (scripts/guides/capture.spec.ts) into public/guides/shots and shots.json.
 * shortcut: guides are code-managed, not CMS-editable yet; move them into the CMS "guide" type when editors need to change them.
 */
export type Audience = "client" | "staff";
export type ClientCat =
  "start" | "apply" | "pay" | "track" | "docs" | "account";
export type StaffCat = "team" | "cases" | "finance";
export type GuideCat = ClientCat | StaffCat;

/** One rectangle the screenshot points at, in % of the image. */
export type Mark = { x: number; y: number; w: number; h: number };
export type ShotData = { w: number; h: number; marks: (Mark | null)[]; /** image path, set by guideShots() */ src?: string };

export type Step = {
  /** what to do, one short sentence; **bold** marks the button/field name */
  text: string;
  /** screenshot id (shots.json) */
  shot?: string;
  /** labels for that screenshot's marks, in capture order; "" hides a mark */
  marks?: string[];
  caption?: string;
};
export type Section = {
  id: string;
  title: string;
  intro?: string;
  steps?: Step[];
  tips?: string[];
  warn?: string;
  faq?: { q: string; a: string }[];
};
export type GuideText = {
  title: string;
  summary: string;
  /** Irembo-style facts box */
  facts?: { who?: string; time?: string; cost?: string; need?: string[] };
  sections: Section[];
  /** search-only words (synonyms, abbreviations) */
  keywords?: string;
};
export type Guide = {
  slug: string;
  audience: Audience;
  cat: GuideCat;
  /** service slug this guide walks through (service page links here) */
  service?: string;
  minutes: number;
  updated: string;
  popular?: boolean;
  t: Record<Locale, GuideText>;
};
